CREATE OR REPLACE FUNCTION public.tms_extended_selftest() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); claims text; test_role public.app_role; checks jsonb:='[]'; k text; payload jsonb; a jsonb; b jsonb; outcome jsonb; r public.app_records%ROWTYPE; BEGIN IF NOT public.tms_module('/usuarios') THEN RAISE EXCEPTION 'Apenas administradores ativos'; END IF; claims:=current_setting('request.jwt.claims',true); FOREACH test_role IN ARRAY ARRAY['comercial','operacao','financeiro']::public.app_role[] LOOP BEGIN UPDATE public.user_roles SET role=test_role WHERE user_id=uid; IF public.tms_module('/usuarios') OR public.tms_module('/configuracoes') THEN RAISE EXCEPTION 'Admin privileges leaked'; END IF; IF public.tms_module('/financeiro') IS DISTINCT FROM (test_role='financeiro') OR public.tms_module('/clientes') IS DISTINCT FROM (test_role='comercial') OR public.tms_module('/coletas') IS DISTINCT FROM (test_role='operacao') THEN RAISE EXCEPTION 'Incorrect role mapping'; END IF; IF test_role<>'financeiro' AND EXISTS(SELECT 1 FROM jsonb_array_elements(public.tms_records_read()) x WHERE x->>'collection'='orders' AND (x->'data' ? 'cteValor' OR x->'data' ? 'xmlOriginal')) THEN RAISE EXCEPTION 'Financial fields leaked'; END IF; checks:=checks||jsonb_build_array(test_role::text||': positive/negative access and redaction passed'); RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Rollback role test'; EXCEPTION WHEN no_data_found THEN NULL; END; END LOOP; BEGIN k:=repeat('8',12)||lpad(floor(random()*1e15)::bigint::text,15,'0')||repeat('4',17); payload:=jsonb_build_object('chaveNFe',k,'xmlOriginal','<NFe><infNFe Id="NFe'||k||'"/></NFe>','remetenteCnpj','SELFTEST-SENDER','destinatarioCnpj','SELFTEST-RECIPIENT','numeroNFe','TEST','valorFrete',0,'peso',1,'origemValor','','stage','aguarda_vinculacao','timeline','[]'::jsonb,'costs',jsonb_build_object('execMode','')); a:=public.tms_import_nfe_worker(payload); IF a->>'status'<>'importado' THEN RAISE EXCEPTION 'NF-e failed'; END IF; b:=public.tms_import_nfe_worker(payload||jsonb_build_object('chaveNFe',left(k,43)||'5','xmlOriginal','<NFe><infNFe Id="NFe'||left(k,43)||'5"/></NFe>')); IF a->>'rota' IS DISTINCT FROM b->>'rota' OR a->>'oc' IS DISTINCT FROM b->>'oc' THEN RAISE EXCEPTION 'NF grouping failed'; END IF; outcome:=public.tms_import_nfe_worker(payload); IF outcome->>'status'<>'duplicado' THEN RAISE EXCEPTION 'NF dedupe failed'; END IF; SELECT * INTO r FROM public.app_records WHERE collection='orders' AND data->>'chaveNFe'=k; PERFORM public.tms_records_commit(jsonb_build_array(jsonb_build_object('collection','orders','id',r.id,'version',r.version,'data',r.data||jsonb_build_object('observacao','restore-test'))),'SELFTEST restore merge'); IF NOT EXISTS(SELECT 1 FROM public.app_records WHERE collection='orders' AND id=r.id AND data->>'observacao'='restore-test') THEN RAISE EXCEPTION 'Restore readback failed'; END IF; checks:=checks||jsonb_build_array('Headless NF-e grouped into one route and OC: passed','NF-e repeated: deduplicated','Transactional restore merge/readback: passed'); RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Rollback imports'; EXCEPTION WHEN no_data_found THEN NULL; END; PERFORM set_config('request.jwt.claims',claims,true); RETURN jsonb_build_object('status','passed','checks',checks,'data_persisted',false); END $$;
REVOKE ALL ON FUNCTION public.tms_extended_selftest() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.tms_extended_selftest() TO authenticated;